const items = $input.all();
const out = [];
for (const item of items) {
  const j = item.json;
  if (!j || !j.id || !j.position) continue; // skip RemoteOK legal-notice row
  const url = j.url ? (j.url.startsWith('http') ? j.url : `https://remoteok.com${j.url}`) : '';
  out.push({
    json: {
      job_title: j.position || '',
      company: j.company || '',
      job_url: url,
      source: 'Remote OK',
      location_text: j.location || 'Not specified',
      salary: (j.salary_min || j.salary_max) ? `${j.salary_min || ''}-${j.salary_max || ''}`.replace(/^-|-$/g, '') : '',
      description: (j.description || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim(),
      posted_date: j.date || '',
      tags: Array.isArray(j.tags) ? j.tags.join(', ') : '',
    },
  });
}
return out;

const body = $input.first().json;
const jobs = body.jobs || [];
return jobs.map((j) => ({
  json: {
    job_title: j.title || '',
    company: j.company_name || '',
    job_url: j.url || '',
    source: 'Remotive',
    location_text: j.candidate_required_location || 'Not specified',
    salary: j.salary || '',
    description: (j.description || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim(),
    posted_date: j.publication_date || '',
    tags: Array.isArray(j.tags) ? j.tags.join(', ') : (j.category || ''),
  },
}));

const items = $input.all();
return items.map((item) => {
  const j = item.json;
  const title = j.title || '';
  const parts = title.split(':');
  const company = parts.length > 1 ? parts[0].trim() : '';
  const job_title = parts.length > 1 ? parts.slice(1).join(':').trim() : title;
  return {
    json: {
      job_title,
      company,
      job_url: j.link || '',
      source: 'We Work Remotely',
      location_text: 'Not specified',
      salary: '',
      description: (j.contentSnippet || j.content || j.summary || '').toString().trim(),
      posted_date: j.pubDate || j.isoDate || '',
      tags: Array.isArray(j.categories) ? j.categories.join(', ') : '',
    },
  };
});

const body = $input.first().json;
const jobs = body.jobs || [];
return jobs.map((j) => {
  const company = j.companyName || (j.company && j.company.name) || '';
  const url = j.applicationLink || j.link || (j.guid ? `https://himalayas.app/jobs/${j.guid}` : '');
  const locations = Array.isArray(j.locationRestrictions) && j.locationRestrictions.length
    ? j.locationRestrictions.join(', ')
    : 'Worldwide / Not specified';
  return {
    json: {
      job_title: j.title || '',
      company,
      job_url: url,
      source: 'Himalayas',
      location_text: locations,
      salary: (j.min_salary || j.max_salary) ? `${j.min_salary || ''}-${j.max_salary || ''}`.replace(/^-|-$/g, '') : '',
      description: (j.description || j.excerpt || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim(),
      posted_date: j.pubDate || j.publishedAt || '',
      tags: Array.isArray(j.categories) ? j.categories.join(', ') : '',
    },
  };
});

const KEYWORDS = [
  'async remote', 'asynchronous remote', 'worldwide remote', 'global remote', 'work from anywhere',
  'remote data analyst', 'remote data scientist', 'remote ai marketing', 'remote marketing analyst',
  'remote growth analyst', 'remote bi analyst', 'remote automation specialist', 'remote ai workflow consultant',
  // Fallback terms so single-word job titles at remote-friendly companies aren't missed.
  'data analyst', 'data scientist', 'business intelligence', 'marketing analyst', 'growth analyst',
  'automation specialist', 'ai workflow', 'remote',
];

return $input.all().filter((item) => {
  const j = item.json;
  const haystack = `${j.job_title} ${j.description} ${j.tags}`.toLowerCase();
  return KEYWORDS.some((k) => haystack.includes(k));
});

const newItems = $input.all();
let existing = [];
try {
  existing = $('Read Existing Raw Jobs').all().map((i) => (i.json.job_url || '').toString().trim()).filter(Boolean);
} catch (e) {
  existing = [];
}
const existingUrls = new Set(existing);
const seenInBatch = new Set();
const out = [];

for (const item of newItems) {
  const j = item.json;
  const url = (j.job_url || '').trim();
  const backupKey = `${(j.company || '').trim().toLowerCase()}|${(j.job_title || '').trim().toLowerCase()}`;
  const key = url || backupKey;
  if (!key || key === '|') continue;
  if (url && existingUrls.has(url)) continue;
  if (seenInBatch.has(key)) continue;
  seenInBatch.add(key);
  existingUrls.add(url);
  out.push({
    json: {
      ...j,
      job_id: Buffer.from(key).toString('base64').slice(0, 24),
      date_found: new Date().toISOString().slice(0, 10),
    },
  });
}
return out;

const REJECT_PHRASES = [
  'us only', 'u.s. only', 'usa only', 'canada only', 'uk only', 'u.k. only', 'eu only', 'europe only',
  'australia only', 'must be based in', 'must live in', 'must be authorized to work in',
  'local work permit required', 'hybrid', 'onsite', 'on-site', 'office required',
  'remote within country only', 'fixed us hours', 'fixed eu hours',
];

const KEEP_PHRASES = [
  'worldwide remote', 'global remote', 'work from anywhere', 'anywhere', 'apac remote',
  'international contractors accepted', 'contractor role', 'b2b contractor', 'hires via deel',
  'hires via remote.com', 'hires via oyster', 'eor supported', 'remote first', 'distributed team',
];

return $input.all().map((item) => {
  const j = item.json;
  const text = `${j.job_title} ${j.description} ${j.location_text} ${j.tags}`.toLowerCase();
  const matchedReject = REJECT_PHRASES.find((p) => text.includes(p));
  const matchedKeep = KEEP_PHRASES.filter((p) => text.includes(p));
  return {
    json: {
      ...j,
      hardFilter: matchedReject ? 'reject' : 'pass',
      hardFilterReason: matchedReject || '',
      keepSignals: matchedKeep.join(', '),
    },
  };
});

return $input.all().map((item) => {
  const j = item.json;
  return {
    json: {
      date_rejected: new Date().toISOString().slice(0, 10),
      job_title: j.job_title,
      company: j.company,
      job_url: j.job_url,
      reason: `Hard filter: matched "${j.hardFilterReason}"`,
      reject_category: 'hard_filter',
    },
  };
});

const aiResponses = $input.all();
const originalJobs = $('Eligible For AI Check').all();
const out = [];

for (let i = 0; i < aiResponses.length; i++) {
  const resp = aiResponses[i].json;
  const orig = (originalJobs[i] && originalJobs[i].json) || {};
  let aiText = '';
  try {
    aiText = resp.content[0].text;
  } catch (e) {
    aiText = '';
  }
  let parsed = null;
  try {
    const match = aiText.match(/\{[\s\S]*\}/);
    parsed = JSON.parse(match ? match[0] : aiText);
  } catch (e) {
    parsed = {
      taiwan_eligible: 'unclear',
      reason: 'AI response could not be parsed — flagged for manual check.',
      location_risk: 'medium',
      timezone_risk: 'medium',
      contractor_possible: 'unclear',
      decision: 'manual_check',
    };
  }
  out.push({
    json: {
      ...orig,
      ai_taiwan_eligible: parsed.taiwan_eligible,
      ai_reason: parsed.reason,
      ai_location_risk: parsed.location_risk,
      ai_timezone_risk: parsed.timezone_risk,
      ai_contractor_possible: parsed.contractor_possible,
      ai_decision: parsed.decision,
    },
  });
}
return out;

const ASYNC_REJECT = [
  'strict 9 to 5', 'strict 9-5', 'fixed us hours', 'fixed est hours', 'fixed pst hours', 'fixed cet hours',
  'daily live calls required', 'must overlap full business day',
];

const ROLE_CORE = [
  'data analyst', 'data scientist', 'junior data scientist', 'business intelligence analyst', 'bi analyst',
  'marketing analyst', 'performance marketing analyst', 'growth analyst', 'ai marketing specialist',
  'ai automation specialist', 'ai workflow consultant', 'creative strategist', 'martech analyst',
];

return $input.all().map((item) => {
  const j = item.json;
  const text = `${j.job_title} ${j.description} ${j.tags}`.toLowerCase();

  const asyncRejectHit = ASYNC_REJECT.some((p) => text.includes(p));
  let asyncLevel = 'none';
  let asyncPoints = 0;
  if (!asyncRejectHit) {
    if (text.includes('async') || text.includes('asynchronous')) {
      asyncLevel = 'high';
      asyncPoints = 25;
    } else if (text.includes('flexible hours') || text.includes('flexible schedule')) {
      asyncLevel = 'medium';
      asyncPoints = 20;
    } else if (text.includes('distributed team')) {
      asyncLevel = 'medium';
      asyncPoints = 15;
    } else if (text.includes('remote first') || text.includes('remote-first')) {
      asyncLevel = 'low';
      asyncPoints = 10;
    }
  }

  const roleMatch = ROLE_CORE.find((r) => text.includes(r));
  const isAdjacent = !roleMatch && (text.includes('marketing') || text.includes('data') || text.includes('analytics'));
  const roleCategory = roleMatch || (isAdjacent ? 'adjacent role' : 'not matched');
  const rolePoints = roleMatch ? 25 : (isAdjacent ? 15 : 0);

  const taiwanEligible = (j.ai_taiwan_eligible || 'unclear').toString().toLowerCase();
  const locationRisk = (j.ai_location_risk || 'medium').toString().toLowerCase();
  const timezoneRisk = (j.ai_timezone_risk || 'medium').toString().toLowerCase();
  const worldwideSignal = /(worldwide remote|global remote|work from anywhere|international contractors|hires via (deel|remote\.com|oyster)|eor supported)/.test(text);
  const apacSignal = /apac remote|apac timezone|asia pacific remote/.test(text);

  let taiwanPoints = 0;
  if (taiwanEligible === 'yes' && (worldwideSignal || locationRisk === 'low')) {
    taiwanPoints = 40;
  } else if (apacSignal) {
    taiwanPoints = 30;
  } else if (taiwanEligible === 'unclear' && locationRisk !== 'high') {
    taiwanPoints = 20;
  }

  const salaryText = (j.salary || '').toString();
  const salaryNums = salaryText.match(/\d[\d,]*/g);
  let salaryMin = salaryNums && salaryNums.length ? Math.min(...salaryNums.map((n) => parseInt(n.replace(/,/g, ''), 10))) : null;
  let salaryPoints = 0;
  if (salaryText) salaryPoints = 10;
  let effectiveMonthly = salaryMin;
  if (salaryMin && salaryMin > 20000) effectiveMonthly = salaryMin / 12; // looks like an annual figure
  if (effectiveMonthly && effectiveMonthly >= 3000) salaryPoints = 15;
  if (effectiveMonthly && effectiveMonthly >= 5000) salaryPoints = 25;

  const score = Math.min(100, taiwanPoints + asyncPoints + rolePoints + salaryPoints);

  let decision = 'reject';
  if (taiwanEligible === 'no' || locationRisk === 'high' || timezoneRisk === 'high' || score < 70) {
    decision = 'reject';
  } else if (
    taiwanEligible === 'yes' &&
    score >= 85 &&
    (asyncLevel === 'high' || asyncLevel === 'medium') &&
    locationRisk === 'low' &&
    (timezoneRisk === 'low' || timezoneRisk === 'medium')
  ) {
    decision = 'apply';
  } else if (taiwanEligible === 'unclear' && score >= 85 && locationRisk === 'medium') {
    decision = 'manual_check';
  } else if (score >= 70) {
    decision = 'keep_review';
  }

  const fitNotes = [];
  if (roleMatch) fitNotes.push(`Strong role fit (${roleMatch})`);
  if (asyncLevel !== 'none') fitNotes.push(`Async level: ${asyncLevel}`);
  if (worldwideSignal) fitNotes.push('Worldwide/anywhere remote signal found');

  return {
    json: {
      ...j,
      async_level: asyncLevel,
      role_category: roleCategory,
      score,
      taiwan_eligible: taiwanEligible,
      location_risk: locationRisk,
      timezone_risk: timezoneRisk,
      contractor_possible: j.ai_contractor_possible || 'unclear',
      taiwan_reason: j.ai_reason || '',
      why_good_fit: fitNotes.join('. '),
      decision,
    },
  };
});

return $input.all().map((item) => {
  const j = item.json;
  const reasons = [];
  if ((j.taiwan_eligible || '').toLowerCase() === 'no') reasons.push('Taiwan eligibility: no');
  if ((j.location_risk || '').toLowerCase() === 'high') reasons.push('location risk: high');
  if ((j.timezone_risk || '').toLowerCase() === 'high') reasons.push('timezone risk: high');
  if ((j.score || 0) < 70) reasons.push(`score below 70 (${j.score})`);
  const reason = `${reasons.join('; ')}${j.taiwan_reason ? ' — AI: ' + j.taiwan_reason : ''}`;
  return {
    json: {
      date_rejected: new Date().toISOString().slice(0, 10),
      job_title: j.job_title,
      company: j.company,
      job_url: j.job_url,
      reason: reason || 'Did not meet eligibility/score threshold',
      reject_category: 'ai_score',
    },
  };
});

const responses = $input.all();
const originals = $('Cover Letter Eligible').all();
return responses.map((item, i) => {
  const resp = item.json;
  const orig = (originals[i] && originals[i].json) || {};
  let letter = '';
  try {
    letter = resp.content[0].text;
  } catch (e) {
    letter = 'Cover letter generation failed — write manually.';
  }
  return { json: { ...orig, cover_letter_draft: letter } };
});

const all = ($input.first().json.data) || [];
const kept = all.filter((x) => x.decision && x.decision !== 'reject' && typeof x.score === 'number');
const manual = all.filter((x) => (x.taiwan_eligible || '').toLowerCase() === 'unclear' && (x.score || 0) >= 70);
const rejected = all.filter((x) => x.reject_category || x.decision === 'reject');

const top = kept.sort((a, b) => (b.score || 0) - (a.score || 0)).slice(0, 10);

function jobBlock(j, i) {
  return `${i + 1}. ${j.job_title}
Company: ${j.company}
Score: ${j.score}
Taiwan eligible: ${j.taiwan_eligible}
Reason: ${j.taiwan_reason || ''}
Async level: ${j.async_level}
Timezone risk: ${j.timezone_risk}
Salary: ${j.salary || 'Not listed'}
Why it fits Jerry: ${j.why_good_fit || ''}
Apply link: ${j.job_url}`;
}

const topBlock = top.length ? top.map(jobBlock).join('\n\n') : 'No jobs cleared the bar today.';
const manualBlock = manual.length
  ? manual.map((j) => `- ${j.job_title} at ${j.company} (score ${j.score}) — ${j.job_url}`).join('\n')
  : 'None';

const countBy = (pred) => rejected.filter(pred).length;
const usOnly = countBy((j) => /us only|u\.s\. only|usa only/i.test(j.reason || ''));
const euOnly = countBy((j) => /eu only|europe only/i.test(j.reason || ''));
const hybrid = countBy((j) => /hybrid|onsite|on-site/i.test(j.reason || ''));
const tzRisk = countBy((j) => /timezone|fixed .* hours/i.test(j.reason || ''));

const message = `Daily Taiwan Eligible Async Remote Jobs

Top jobs today:

${topBlock}

Manual check:
${manualBlock}

Rejected summary:
Number rejected because of US only: ${usOnly}
Number rejected because of EU only: ${euOnly}
Number rejected because of hybrid: ${hybrid}
Number rejected because of timezone risk: ${tzRisk}
Total rejected: ${rejected.length}`;

return [{ json: { digest: message, top_count: top.length, rejected_count: rejected.length } }];
